// Lê o pacote que a Meta mandou, confere a assinatura e separa cada evento
// (uma chamada pode trazer várias mensagens) em um item padronizado.
const cfg = $('Configurações').first().json;
// O Webhook tem duas saídas (GET e POST); a mensagem chega pela segunda.
// A etapa da assinatura repassa o pedido inteiro, então lemos dela.
const req = $('Calcular Assinatura da Meta').first().json;
const headers = req.headers || {};
const body = req.body || {};

const assinaturaRecebida = String(headers['x-hub-signature-256'] || '');
let assinaturaCalculada = '';
try {
  assinaturaCalculada = String($('Calcular Assinatura da Meta').first().json.assinaturaCalculada || '');
} catch (e) {
  assinaturaCalculada = '';
}
const assinaturaValida = !!assinaturaCalculada && assinaturaRecebida === 'sha256=' + assinaturaCalculada;
const modoAssinatura = String(cfg.modoAssinatura || 'avisar').toLowerCase();

if (modoAssinatura === 'bloquear' && !assinaturaValida) {
  return [{ json: { tipo: 'ignorar', motivo: 'assinatura_invalida', assinaturaValida } }];
}

const comandoVoltar = String(cfg.comandoVoltarMaya || '#maya').toLowerCase().trim();
const ttlPausa = Math.max(60, Math.round(Number(cfg.horasPausaHumano || 6) * 3600));
const saida = [];

// Palavras que fazem um comentário virar conversa no Direct. "*" = qualquer comentário.
const semAcento = (t) => String(t || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
const palavras = String(cfg.palavrasComentario || '').split(',').map(semAcento).map(p => p.trim()).filter(Boolean);
const contaPropria = String(cfg.igContaId || '');

const eventos = [];
for (const entry of body.entry || []) {
  for (const ev of entry.messaging || []) eventos.push({ ev, contaEntrada: entry.id });
  for (const ch of entry.changes || []) {
    if (ch.field === 'messages' && ch.value) eventos.push({ ev: ch.value, contaEntrada: entry.id });
    if (ch.field === 'comments' && ch.value) {
      const c = ch.value;
      const autor = String(c.from?.id || '');
      const textoComentario = String(c.text || '').trim();
      const casou = palavras.includes('*') || palavras.some(p => semAcento(textoComentario).includes(p));
      if (!c.id || !autor || autor === String(entry.id) || autor === contaPropria) {
        saida.push({ json: { tipo: 'ignorar', motivo: 'comentario_da_propria_conta', assinaturaValida } });
      } else if (!casou) {
        saida.push({ json: { tipo: 'ignorar', motivo: 'comentario_sem_palavra_chave', assinaturaValida } });
      } else {
        saida.push({
          json: {
            tipo: 'comentario',
            clienteId: autor,
            contaId: String(entry.id || contaPropria),
            comentarioId: String(c.id),
            username: String(c.from?.username || ''),
            texto: textoComentario.slice(0, 1000),
            assinaturaValida,
            ttlPausa,
            chaveComentario: `ig:coment:${c.id}`,
            chaveMemoria: `ig:memoria:${autor}`,
            chaveHumano: `ig:humano:${autor}`
          }
        });
      }
    }
  }
}
eventos.sort((a, b) => Number(a.ev.timestamp || 0) - Number(b.ev.timestamp || 0));

for (const { ev, contaEntrada } of eventos) {
  const msg = ev.message;
  if (!msg && !ev.postback) {
    const motivo = ev.read ? 'leitura' : ev.reaction ? 'reacao' : ev.message_edit ? 'edicao' : ev.delivery ? 'entrega' : 'outro_evento';
    saida.push({ json: { tipo: 'ignorar', motivo, assinaturaValida } });
    continue;
  }
  if (msg && (msg.is_deleted || msg.is_unsupported)) {
    saida.push({ json: { tipo: 'ignorar', motivo: msg.is_deleted ? 'mensagem_apagada' : 'nao_suportada', assinaturaValida } });
    continue;
  }

  // Em mensagens "from me" (eco) a Meta inverte os papéis: quem envia é a
  // conta do FlyControl e o cliente aparece como destinatário.
  const ehEco = msg?.is_echo === true;
  const clienteId = String(ehEco ? (ev.recipient?.id || '') : (ev.sender?.id || ''));
  const contaId = String((ehEco ? ev.sender?.id : ev.recipient?.id) || contaEntrada || cfg.igContaId || '');
  if (!clienteId) {
    saida.push({ json: { tipo: 'ignorar', motivo: 'sem_cliente', assinaturaValida } });
    continue;
  }

  const timestamp = Number(ev.timestamp || Date.now());
  const mid = String(msg?.mid || ev.postback?.mid || `${clienteId}-${timestamp}`);
  const anexo = (msg?.attachments || [])[0] || null;
  const tipoAnexo = String(anexo?.type || '');
  const anexoUrl = String(anexo?.payload?.url || '');
  let texto = String(msg?.text || ev.postback?.title || '').trim();

  let tipo = 'texto';
  if (ehEco) tipo = 'eco';
  else if (tipoAnexo === 'audio' && anexoUrl) tipo = 'audio';
  else if (tipoAnexo === 'image' && anexoUrl) tipo = 'imagem';

  if (!ehEco) {
    const complemento = texto ? ' ' + texto : '';
    if (tipoAnexo === 'story_mention') texto = '[O cliente mencionou o perfil do FlyControl em um story dele]' + complemento;
    else if (['share', 'ig_reel', 'reel', 'ig_post'].includes(tipoAnexo)) texto = '[O cliente compartilhou uma publicação ou reel do Instagram]' + complemento;
    else if (tipoAnexo === 'video') texto = '[O cliente enviou um vídeo, que não consigo assistir]' + complemento;
    else if (tipoAnexo === 'file') texto = '[O cliente enviou um arquivo, que não consigo abrir]' + complemento;
    else if (tipoAnexo && tipo === 'texto') texto = '[O cliente enviou uma figurinha ou curtida]' + complemento;
    if (msg?.reply_to?.story) texto = '[Resposta a um story do FlyControl] ' + texto;
    if (tipo === 'texto' && !texto) texto = '[O cliente enviou uma mensagem sem texto]';
    texto = texto.slice(0, 3000);
  }

  saida.push({
    json: {
      tipo,
      clienteId,
      contaId,
      mid,
      timestamp,
      texto,
      tipoAnexo,
      anexoUrl,
      comando: ehEco && comandoVoltar && texto.toLowerCase().includes(comandoVoltar) ? 'liberar' : '',
      assinaturaValida,
      ttlPausa,
      chaveMid: `ig:mid:${mid}`,
      chaveMarcaMaya: `ig:maya_mid:${mid}`,
      chaveHumano: `ig:humano:${clienteId}`,
      chaveRate: `ig:rate:${clienteId}`,
      chaveBuffer: `ig:buffer:${clienteId}`,
      chaveUltima: `ig:ultima:${clienteId}`,
      chaveMemoria: `ig:memoria:${clienteId}`,
      chaveLead: `ig:lead:${clienteId}`
    }
  });
}

return saida;

// Junta as mensagens agrupadas do cliente e monta o contexto que a Maya recebe
// (hora em Brasília, se a equipe está no horário e o nome do cliente).
const cfg = $('Configurações').first().json;
const ev = $('Separar Eventos').item.json;
const bruto = $('Ler Mensagens Agrupadas').item.json.buffer;

let partes = Array.isArray(bruto) ? bruto : (bruto ? [bruto] : []);
partes = partes.map(p => String(p).trim()).filter(Boolean);
if (!partes.length) partes = [ev.texto];

let perfil = {};
try {
  perfil = $('Buscar Perfil do Cliente').item.json || {};
} catch (e) {
  perfil = {};
}

const agora = DateTime.now().setZone('America/Sao_Paulo').setLocale('pt-BR');
const dentroHorario = agora.hour >= Number(cfg.horaAbre ?? 7) && agora.hour < Number(cfg.horaFecha ?? 23);

return {
  json: {
    clienteId: ev.clienteId,
    contaId: ev.contaId,
    mid: ev.mid,
    chaveMemoria: ev.chaveMemoria,
    chaveHumano: ev.chaveHumano,
    chaveLead: ev.chaveLead,
    ttlPausa: ev.ttlPausa,
    nome: perfil.name || '',
    username: perfil.username || '',
    mensagemCliente: partes.join('\n'),
    dataHora: agora.toFormat("cccc, dd/LL/yyyy 'às' HH:mm"),
    dentroHorario
  }
};

