// Limpa a resposta da Maya, descobre se ela pediu transferência para a equipe
// e quebra textos longos em partes (o Instagram aceita até 1000 caracteres).
const LIMITE = 900;
const contextos = $('Montar Contexto').all();
const saida = [];

const pedidosDoCliente = [
  'falar com atendente', 'falar com um atendente', 'quero um humano', 'atendente humano',
  'falar com alguém', 'falar com alguem', 'falar com uma pessoa', 'pessoa de verdade', 'falar com humano'
];
const frasesDeTransferencia = [
  'vou chamar um atendente', 'vou chamar alguém da nossa equipe', 'vou chamar alguem da nossa equipe',
  'vou te transferir', 'vou transferir'
];

$input.all().forEach((item, i) => {
  const ctx = contextos[i]?.json || {};
  let resposta = String(item.json.output || '').trim();
  const falhou = !resposta;
  if (falhou) {
    resposta = 'Desculpa, tive uma instabilidade aqui 😅 Já chamei alguém da nossa equipe para continuar com você.';
  }

  const temMarca = /\[\[\s*TRANSFERIR\s*\]\]/i.test(resposta);
  resposta = resposta
    .replace(/\[\[\s*TRANSFERIR\s*\]\]/gi, '')
    .replace(/<\/?contexto>/gi, '')
    .replace(/\*\*(.+?)\*\*/g, '$1')
    .replace(/__(.+?)__/g, '$1')
    .replace(/^#{1,6}\s+/gm, '')
    .replace(/^\s*[-*]\s+/gm, '• ')
    .replace(/\n{3,}/g, '\n\n')
    .trim();

  const textoCliente = String(ctx.mensagemCliente || '').toLowerCase();
  const textoMaya = resposta.toLowerCase();
  let motivo = '';
  if (falhou) motivo = 'falha_da_ia';
  else if (temMarca) motivo = 'maya_transferiu';
  else if (pedidosDoCliente.some(p => textoCliente.includes(p))) motivo = 'cliente_pediu_humano';
  else if (frasesDeTransferencia.some(f => textoMaya.includes(f))) motivo = 'maya_anunciou_transferencia';
  const precisaHumano = !!motivo;

  const trechos = [];
  let atual = '';
  for (const paragrafo of resposta.split(/\n{2,}/)) {
    const junto = atual ? atual + '\n\n' + paragrafo : paragrafo;
    if (junto.length <= LIMITE) {
      atual = junto;
      continue;
    }
    if (paragrafo.length <= LIMITE) {
      trechos.push(atual);
      atual = paragrafo;
      continue;
    }
    let resto = junto;
    while (resto.length > LIMITE) {
      let corte = resto.lastIndexOf(' ', LIMITE);
      if (corte < LIMITE * 0.5) corte = LIMITE;
      trechos.push(resto.slice(0, corte).trim());
      resto = resto.slice(corte).trim();
    }
    atual = resto;
  }
  if (atual) trechos.push(atual);

  trechos.forEach((texto, idx) => {
    saida.push({
      json: {
        clienteId: ctx.clienteId,
        contaId: ctx.contaId,
        nome: ctx.nome,
        username: ctx.username,
        chaveHumano: ctx.chaveHumano,
        chaveLead: ctx.chaveLead,
        ttlPausa: ctx.ttlPausa,
        mensagemCliente: ctx.mensagemCliente,
        respostaCompleta: resposta,
        texto,
        ordem: idx + 1,
        totalTrechos: trechos.length,
        primeiroTrecho: idx === 0,
        precisaHumano,
        motivoTransferencia: motivo
      },
      pairedItem: { item: i }
    });
  });
});

return saida;

